/* ================= CONTACTS — database, folders, DNC, health, profile ================= */
S.ct={tab:'all',view:'rows',folder:null,camp:null,filters:[],match:'all',q:'',sel:new Set(),sort:'name',fcur:null,fsel:null,fsort:'name',aiMsg:null,hsel:new Set(),found:{}};
TITLES.contacts=()=>'<b>Contacts</b>'+(S.ct.folder?' › '+esc(fName(S.ct.folder)):'');
const fName=id=>(D.folders.find(f=>f.id===id)||{name:'—'}).name;
const fKids=id=>D.folders.filter(f=>f.parent===id);
const fIds=id=>[id].concat(fKids(id).flatMap(k=>fIds(k.id)));
const fPath=id=>{const out=[];let f=D.folders.find(x=>x.id===id);while(f){out.unshift(f);f=D.folders.find(x=>x.id===f.parent)}return out};

/* ---------- filters ---------- */
const WITHIN=[['7','last 7 days'],['30','last 30 days'],['90','last 3 months'],['180','last 6 months'],['365','last 12 months'],['9999','any time']];
const uniq=a=>[...new Set(a)];
const FIELDS=[
 {k:'name',g:'Person',l:'Name contains',type:'text',def:'',test:(c,v)=>cname(c).toLowerCase().includes(v.toLowerCase()),say:v=>`Name contains “${v}”`},
 {k:'phone',g:'Person',l:'Phone contains',type:'text',def:'',test:(c,v)=>c.phone.replace(/\D/g,'').includes(v.replace(/\D/g,'')),say:v=>`Phone contains ${v}`},
 {k:'hasEmail',g:'Person',l:'Has an email',type:'yn',def:'yes',test:(c,v)=>!!c.email===(v==='yes'),say:v=>v==='yes'?'Has an email':'Missing email'},
 {k:'hasName',g:'Person',l:'Has a name',type:'yn',def:'no',test:(c,v)=>!!c.name===(v==='yes'),say:v=>v==='yes'?'Has a name':'Missing name'},
 {k:'gender',g:'Person',l:'Gender',type:'one',opts:[['F','Female'],['M','Male']],def:'F',test:(c,v)=>c.gender===v,say:v=>v==='F'?'Women':'Men'},
 {k:'age',g:'Person',l:'Age',type:'range',def:[25,45],test:(c,v)=>c.age>=v[0]&&c.age<=v[1],say:v=>`Age ${v[0]}–${v[1]}`},
 {k:'lang',g:'Person',l:'Language',type:'multi',opts:['English','Urdu','Spanish'],def:['Urdu'],test:(c,v)=>v.includes(c.lang),say:v=>'Speaks '+v.join(' or ')},
 {k:'zip',g:'Location',l:'Zip / postal codes',type:'tags',def:[],ph:'Type a code, press Enter (e.g. L5B, 11215)',test:(c,v)=>v.some(z=>c.zip.toLowerCase().startsWith(z.toLowerCase())),say:v=>'Postal code '+v.join(', ')},
 {k:'addr',g:'Location',l:'Addresses / streets',type:'tags',def:[],ph:'Type a street, press Enter (e.g. King St W)',test:(c,v)=>v.some(a=>c.address.toLowerCase().includes(a.toLowerCase())),say:v=>'Address has '+v.join(', ')},
 {k:'city',g:'Location',l:'City / neighbourhood',type:'multi',opts:uniq(D.contacts.map(c=>c.city)),def:['Mississauga'],test:(c,v)=>v.includes(c.city),say:v=>'In '+v.join(' or ')},
 {k:'country',g:'Location',l:'Country',type:'multi',opts:['Canada','United States','Pakistan'],def:['Canada'],test:(c,v)=>v.includes(c.country),say:v=>v.join(' or ')},
 {k:'bought',g:'Purchases',l:'Bought a product',type:'bought',def:{p:'any',w:'90'},test:(c,v)=>!!c.purchase&&(v.p==='any'||c.purchase.product===v.p)&&(new Date(dISO(0))-new Date(c.purchase.date))/864e5<=+v.w,say:v=>`Bought ${v.p==='any'?'anything':v.p} in the ${WITHIN.find(x=>x[0]===v.w)[1]}`},
 {k:'never',g:'Purchases',l:'Never bought',type:'none',def:true,test:c=>!c.purchase,say:()=>'Never bought'},
 {k:'stage',g:'Campaigns & stages',l:'Stage',type:'multi',opts:uniq(Object.values(D.stages).flatMap(p=>[...p.out,...p.in].map(s=>s.n))),def:['Interested'],test:(c,v)=>v.includes(c.stage),say:v=>'Stage is '+v.join(' or ')},
 {k:'camp',g:'Campaigns & stages',l:'Campaign',type:'multi',opts:D.campaigns.map(c=>[c.id,c.name]),def:['k1'],test:(c,v)=>v.includes(c.camp),say:v=>'In '+v.map(x=>(camp(x)||{name:x}).name).join(' or ')},
 {k:'folder',g:'Campaigns & stages',l:'Lead folder',type:'multi',opts:D.folders.filter(f=>!f.grp).map(f=>[f.id,f.name]),def:['f1'],test:(c,v)=>v.includes(c.folder),say:v=>'Folder '+v.map(fName).join(' or ')},
 {k:'dir',g:'Source',l:'Inbound or outbound',type:'one',opts:[['in','Inbound'],['out','Outbound / uploaded']],def:'in',test:(c,v)=>c.dir===v,say:v=>v==='in'?'Inbound leads':'Outbound / uploaded leads'},
 {k:'source',g:'Source',l:'Lead source',type:'multi',opts:D.sources.map(s=>s.n),def:['Landing page'],test:(c,v)=>v.includes(c.source),say:v=>'Source: '+v.join(', ')},
 {k:'contacted',g:'Activity',l:'Last contacted',type:'recency',def:{m:'out',d:'30'},test:(c,v)=>v.m==='in'?c.last<=+v.d:c.last>+v.d,say:v=>`${v.m==='in'?'Contacted':'Not contacted'} in the last ${v.d} days`},
 {k:'score',g:'Activity',l:'Lead score',type:'multi',opts:['Hot','Warm','Cold','Not responding','Dead'],def:['Hot'],test:(c,v)=>v.includes(scoreOf(c)),say:v=>'Score: '+v.join(', ')},
 {k:'agent',g:'Activity',l:'Talked to agent',type:'multi',opts:D.agents.map(a=>[a.id,a.name]),def:['s1'],test:(c,v)=>v.includes(c.agent),say:v=>'Talked to '+v.map(agName).join(' or ')},
 {k:'consent',g:'Permission',l:'Agreed to texts',type:'yn',def:'yes',test:(c,v)=>c.consent.sms===(v==='yes'),say:v=>v==='yes'?'Agreed to texts':'Not agreed to texts'},
 {k:'dnc',g:'Permission',l:'On Do-Not-Contact',type:'yn',def:'no',test:(c,v)=>c.dnc===(v==='yes'),say:v=>v==='yes'?'On Do-Not-Contact':'Not on Do-Not-Contact'},
 {k:'carrier',g:'Your custom fields',l:'Current carrier',demo:1},{k:'budget',g:'Your custom fields',l:'Budget',demo:1},{k:'ins',g:'Your custom fields',l:'Insurance provider',demo:1},
 {k:'opened',g:'Activity',l:'Opened an email',demo:1},{k:'answered',g:'Activity',l:'Answered a call',demo:1},{k:'noshow',g:'Activity',l:'Missed an appointment',demo:1},{k:'tag',g:'Person',l:'Tag',demo:1},{k:'created',g:'Source',l:'Date added',demo:1},
];
FIELDS.forEach(f=>{if(f.demo){f.type='text';f.def='';f.test=()=>true;f.say=v=>`${f.l}: ${v||'any'}`}});
const FD=Object.fromEntries(FIELDS.map(f=>[f.k,f]));
const sayF=f=>FD[f.k].say(f.v);
function runFilters(list,fl,match){const act=fl.filter(f=>!FD[f.k].demo&&!(Array.isArray(f.v)&&!f.v.length));if(!act.length)return list;return list.filter(c=>{const r=act.map(f=>!!FD[f.k].test(c,f.v));return match==='any'?r.some(Boolean):r.every(Boolean)})}
function parseNL(t){t=t.toLowerCase();const f=[];
  const cities=uniq(D.contacts.map(c=>c.city)).filter(c=>t.includes(c.toLowerCase()));if(cities.length)f.push({k:'city',v:cities});
  const pc=t.match(/\b([a-z]\d[a-z]|\d{5})\b/gi);if(pc)f.push({k:'zip',v:pc.map(x=>x.toUpperCase())});
  if(/\b(women|woman|female|ladies)\b/.test(t))f.push({k:'gender',v:'F'});else if(/\b(men|man|male)\b/.test(t))f.push({k:'gender',v:'M'});
  const m=t.match(/(?:last|past)\s+(\d+|few|couple of)?\s*(day|week|month|year)s?/);let w='9999';if(m){const n=m[1]&&/\d/.test(m[1])?+m[1]:(m[1]?3:1);const d=n*{day:1,week:7,month:30,year:365}[m[2]];w=d<=7?'7':d<=30?'30':d<=90?'90':d<=180?'180':d<=365?'365':'9999'}
  if(/never (bought|purchased)|no purchase/.test(t))f.push({k:'never',v:true});else if(/bought|purchased|customer|sold/.test(t)){let p='any';if(/internet|fiber/.test(t))p='Internet 1 Gig';else if(/5g|mobility|unlimited/.test(t))p='5G Unlimited line';else if(/tv/.test(t))p='TV package';f.push({k:'bought',v:{p,w}})}
  if(/(no|without|missing) email/.test(t))f.push({k:'hasEmail',v:'no'});else if(/(with|has|have) (an )?emails?/.test(t))f.push({k:'hasEmail',v:'yes'});
  if(/(no|without|missing) name/.test(t))f.push({k:'hasName',v:'no'});
  if(/\binbound\b/.test(t))f.push({k:'dir',v:'in'});else if(/\boutbound\b|uploaded/.test(t))f.push({k:'dir',v:'out'});
  const a=t.match(/(?:aged?|between)\s*(\d{2})\s*(?:-|to|and)\s*(\d{2})/);if(a)f.push({k:'age',v:[+a[1],+a[2]]});else{const o=t.match(/(?:over|older than)\s*(\d{2})/);if(o)f.push({k:'age',v:[+o[1],99]})}
  const stg=FD.stage.opts.filter(s=>t.includes(s.toLowerCase()));if(stg.length)f.push({k:'stage',v:stg});
  if(/not contacted|haven.?t (been )?contacted/.test(t))f.push({k:'contacted',v:{m:'out',d:'30'}});
  if(/dead|not responding/.test(t))f.push({k:'score',v:[/dead/.test(t)?'Dead':'Not responding']});
  if(/hot lead/.test(t))f.push({k:'score',v:['Hot']});
  return f}
function ctList(){let L=D.contacts;const c=S.ct;
  if(c.folder){const ids=fIds(c.folder);L=L.filter(x=>ids.includes(x.folder))}
  if(c.camp)L=L.filter(x=>x.camp===c.camp);
  L=runFilters(L,c.filters,c.match);
  if(c.q){const s=c.q.toLowerCase();L=L.filter(x=>(cname(x)+' '+x.phone+' '+x.email+' '+x.address+' '+x.city+' '+x.zip+' '+x.stage+' '+x.source+' '+(camp(x.camp)||{name:''}).name).toLowerCase().includes(s))}
  const k=c.sort;L=L.slice().sort((a,b)=>k==='last'?a.last-b.last:k==='stage'?a.stage.localeCompare(b.stage):cname(a).localeCompare(cname(b)));
  return L}
const reach=L=>({sms:L.filter(c=>c.consent.sms&&!c.dnc).length,call:L.filter(c=>c.consent.call&&!c.dnc).length,email:L.filter(c=>c.email&&c.consent.email).length,dnc:L.filter(c=>c.dnc).length});

/* ---------- helpers used everywhere ---------- */
function stgColor(name,cmp){const c=camp(cmp);const s=c?stagesOf(c).find(x=>x.n===name):null;return s?s.c:(Object.values(D.stages).flatMap(p=>[...p.out,...p.in]).find(x=>x.n===name)||{c:'#8A93A6'}).c}
function stagePill(c){const cp=camp(c.camp);return `<span class="stg" data-tip="<b>${esc(c.stage)}</b><br>Campaign: ${esc(cp?cp.name:'—')}<br>Lead source: ${esc(c.source)} (${c.dir==='in'?'inbound':'uploaded / outbound'})"><i style="background:${stgColor(c.stage,c.camp)}"></i>${esc(c.stage)}</span>`}
const scoreBdg=c=>{const s=scoreOf(c);return bdg(s,{Hot:'good',Warm:'blue',Cold:'',['Not responding']:'warn',Dead:'bad'}[s])};
A.openContact=el=>{hidePop();go('contact',{id:el.dataset.id})};
A.openFolder=el=>{S.ct.folder=el.dataset.id;S.ct.view='rows';S.ct.tab='all';S.ct.filters=[];go('contacts')};

/* ---------- main view ---------- */
VIEWS.contacts=()=>{const c=S.ct;const dead=D.contacts.filter(x=>scoreOf(x)==='Dead').length,nr=D.contacts.filter(x=>scoreOf(x)==='Not responding').length;
 const miss={name:D.contacts.filter(x=>!x.name).length,email:D.contacts.filter(x=>!x.email).length,addr:D.contacts.filter(x=>!x.address).length};
 const head=`<div class="ph"><div><h1>Contacts</h1><p class="sub">Your database with every person’s full history. Import lists into folders, filter anything, and start campaigns from any folder.</p></div><div class="row">${btn('Contacts settings','ctSettings',{k:'sm',i:'gear'})}${btn('Import','import',{k:'sm',i:'upload'})}${btn('Add contact','addContact',{k:'sm primary',i:'plus'})}</div></div>
 ${tabs([['all','Contacts',null,'50,214'],['dnc','Do-Not-Contact',null,D.dnc.length],['health','Database health',null,dead+nr]],c.tab,'ctTab')}`;
 if(c.tab==='dnc')return `<div class="page">${head}${vDNC()}</div>`;
 if(c.tab==='health')return `<div class="page">${head}${vHealth()}</div>`;
 const tiles=`<div class="dq"><button data-act="ctView" data-v="folders" data-tip="Open the folders view"><span>${ic('db',13)}Total contacts</span><b>50,214</b><span>${D.folders.filter(f=>!f.grp).length} folders · sample shows 90</span></button>
  <button data-act="ctMissing"><span>${ic('alert',13)}Missing details</span><b>${miss.name+miss.email+miss.addr}</b><span>${miss.name} names · ${miss.email} emails · ${miss.addr} addresses</span></button>
  <button data-act="ctDups"><span>${ic('copy',13)}Duplicates</span><b>1,202</b><span>detected · ${D.dups.length} shown</span></button>
  <button data-act="ctTab" data-v="health"><span>${ic('phoneoff',13)}Dead numbers</span><b>${dead}</b><span>${nr} not responding</span></button>
  <button data-act="ctTab" data-v="dnc"><span>${ic('shield',13)}Do-Not-Contact</span><b>${D.dnc.length}</b><span>skipped in every campaign</span></button>
  <button data-act="ctQuick" data-k="dir" data-v="in"><span>${ic('in',13)}Inbound leads</span><b>${D.contacts.filter(x=>x.dir==='in').length}</b><span>from ads, forms & calls</span></button>
  <button data-act="ctQuick" data-k="score" data-v="Hot"><span>${ic('star',13)}Hot leads</span><b>${D.contacts.filter(x=>scoreOf(x)==='Hot').length}</b><span>replied & interested</span></button></div>`;
 return `<div class="page wide" style="max-width:1480px">${head}${tiles}
 <div class="row nw" style="margin-bottom:10px;gap:10px"><div class="search big grow">${ic('search',17)}<input class="in" placeholder="Search by anything — name, phone, email, address, city, stage, campaign, source" value="${esc(c.q)}" data-inp="ctQ" aria-label="Search contacts"></div>${seg([['rows','Rows','rows'],['folders','Folders','folder']],c.view,'ctView')}</div>
 ${c.view==='folders'?vFolders():vRows()}</div>`};
function vRows(){const c=S.ct;
 return `<div class="card" style="padding:12px;margin-bottom:12px;background:var(--ai-soft);border-color:var(--ai-line)">${aiBox('ctAI','Build filters with AI — e.g. “all women in Mississauga who have emails and bought in the past 3 months”','ctAIGo',{sample:'All women in Mississauga who have emails and bought internet in the past 3 months'})}${c.aiMsg?`<div class="cm x" style="margin-top:10px">${MXI()}<div class="bb small">${c.aiMsg}</div></div>`:''}</div>
 ${c.folder||c.camp?`<div class="openbar" style="margin-bottom:10px">${ic(c.folder?'folder':'megaphone',14)}<span>Showing ${c.folder?'folder':'campaign'}: <b>${esc(c.folder?fPath(c.folder).map(f=>f.name).join(' › '):camp(c.camp).name)}</b></span><span class="grow"></span>${c.folder?btn('Start campaign','fStart',{k:'xs primary',a:`data-id="${c.folder}"`}):''}<button class="btn icon xs ghost" data-act="ctClearOpen" data-tip="Close and show the whole database" aria-label="Close">${ic('x',14)}</button></div>`:''}
 <div class="row" style="margin-bottom:10px">${c.filters.map((f,i)=>`<span class="chipf ${FD[f.k].demo?'demo':''}"><button class="t" data-act="fEdit" data-i="${i}" data-tip="Change this filter">${esc(sayF(f))}</button><button class="x" data-act="fRm" data-i="${i}" aria-label="Remove filter">${ic('x',12)}</button></span>`).join('')}
  ${btn('Add filter','fAdd',{k:'sm',i:'filter'})}${c.filters.length>1?seg([['all','Match all'],['any','Match any']],c.match,'fMatch'):''}${c.filters.length?btn('Clear filters','fClear',{k:'sm ghost'}):''}<span class="grow"></span>${c.filters.length||c.q?btn('Save as folder','saveFolder',{k:'sm',i:'folderplus'}):''}${c.folder&&c.filters.length?btn('Save','saveFolder',{k:'sm primary',a:'data-existing="1"'}):''}</div>
 <div id="ctres">${ctResults()}</div>`}
function ctResults(){const c=S.ct,L=ctList(),r=reach(L),n=c.sel.size,all=L.length&&L.every(x=>c.sel.has(x.id));
 return `<div class="row between" style="margin-bottom:8px"><div class="row"><b style="font-size:16px">${L.length}</b><span class="muted">people${c.filters.length||c.q||c.folder?' match':''}</span><span class="small muted">· ${r.sms} can get texts · ${r.call} calls · ${r.email} emails${r.dnc?` · <button class="btn link small" data-act="ctTab" data-v="dnc">${r.dnc} on Do-Not-Contact</button>`:''}</span></div><div class="row"><span class="small muted">Sort</span>${sel([['name','Name'],['last','Last contacted'],['stage','Stage']],c.sort,'data-chg="ctSort" aria-label="Sort"','sm auto')}${btn('Start a campaign with '+(L.length===D.contacts.length?'everyone':'these '+L.length),'ctCamp',{k:'sm primary',i:'megaphone',d:!L.length})}</div></div>
 ${n?`<div class="banner" style="margin-bottom:8px;background:var(--primary-soft);border-color:transparent"><b>${n} selected</b>${btn('Edit field','bulk',{k:'xs',a:'data-k="edit"'})}${btn('Set stage','bulk',{k:'xs',a:'data-k="stage"'})}${btn('Record sale','bulk',{k:'xs',a:'data-k="sale"'})}${btn('Add tag','bulk',{k:'xs',a:'data-k="tag"'})}${btn('Move to folder','bulk',{k:'xs',a:'data-k="folder"'})}${btn('Add to campaign','bulk',{k:'xs',a:'data-k="camp"'})}${aiBtn('Fill missing data','enrich','','xs')}${btn('Add to Do-Not-Contact','bulk',{k:'xs',a:'data-k="dnc"'})}${btn('Delete','bulk',{k:'xs danger',a:'data-k="del"'})}${btn('Unselect','ctSelNone',{k:'xs ghost'})}</div>`:''}
 <div class="card tw" style="max-height:calc(100vh - 360px);min-height:320px;overflow:auto" id="ctscroll" data-keep><table class="t compact"><thead><tr><th class="cb"><input type="checkbox" data-act="ctSelAll" ${all?'checked':''} aria-label="Select all"></th><th>Name</th><th>Phone</th><th>Email</th><th>Address</th><th>City</th><th>Stage</th><th>Campaign</th><th>Source</th><th>Last purchase</th><th>Date sold</th><th>Last contacted</th><th>Score</th></tr></thead><tbody>
 ${L.map(x=>`<tr class="${c.sel.has(x.id)?'sel':''}"><td class="cb"><input type="checkbox" data-act="ctSel" data-id="${x.id}" ${c.sel.has(x.id)?'checked':''} aria-label="Select"></td>
  <td><div class="nm">${av(x.name||'?','sm')}${x.name?`<button class="lnk" data-act="openContact" data-id="${x.id}">${esc(x.name)}</button>`:`<button class="lnk" data-act="openContact" data-id="${x.id}"><span class="bdg warn">Name missing</span></button>`}</div></td>
  <td><button class="lnk num" data-act="phoneMenu" data-id="${x.id}" data-pop data-tip="Call yourself or let an AI agent call now">${esc(x.phone)}</button></td>
  <td>${x.email?esc(x.email):'<span class="bdg warn">Missing</span>'}</td><td>${x.address?esc(x.address):'<span class="bdg warn">Missing</span>'}</td><td>${esc(x.city)} <span class="faint small">${esc(x.zip)}</span></td>
  <td>${stagePill(x)}</td><td>${x.camp?`<button class="lnk small" data-act="nav" data-v="campaign" data-p='{"id":"${x.camp}"}'>${esc(camp(x.camp).name)}</button>`:'<span class="faint">—</span>'}</td>
  <td><span class="row nw">${dirIc(x.dir)}<span class="small">${esc(x.source)}</span></span></td>
  <td>${x.purchase?`${esc(x.purchase.product)}`:'<span class="faint">—</span>'}</td><td class="num small">${x.sold?dShort(x.sold):x.purchase?dShort(x.purchase.date):'<span class="faint">—</span>'}</td><td class="small">${agoTxt(x.last)}</td><td>${scoreBdg(x)}</td></tr>`).join('')}
 </tbody></table>${L.length?'':empty('No one matches. Try removing a filter.',btn('Clear filters','fClear',{k:'sm'}))}</div>`}
I.ctQ=el=>{S.ct.q=el.value;const r=$('#ctres');if(r)r.innerHTML=ctResults();else if(S.ct.view==='folders'){S.ct.view='rows';rr();const i=$('[data-inp="ctQ"]');i.focus();i.setSelectionRange(i.value.length,i.value.length)}};
A.ctTab=el=>{S.ct.tab=el.dataset.v;rr()};
A.ctView=el=>{S.ct.view=el.dataset.v;S.ct.tab='all';rr()};
A.ctQuick=el=>{S.ct.filters=[{k:el.dataset.k,v:el.dataset.k==='score'?[el.dataset.v]:el.dataset.v}];S.ct.view='rows';rr()};
A.ctClearOpen=()=>{S.ct.folder=null;S.ct.camp=null;rr();renderTop()};
C.ctSort=el=>{S.ct.sort=el.value;$('#ctres').innerHTML=ctResults()};
A.ctSel=el=>{const s=S.ct.sel,id=el.dataset.id;s.has(id)?s.delete(id):s.add(id);$('#ctres').innerHTML=ctResults()};
A.ctSelAll=()=>{const L=ctList(),s=S.ct.sel,all=L.every(x=>s.has(x.id));L.forEach(x=>all?s.delete(x.id):s.add(x.id));$('#ctres').innerHTML=ctResults()};
A.ctSelNone=()=>{S.ct.sel.clear();$('#ctres').innerHTML=ctResults()};
A.ctCamp=()=>newWizard({src:'filter'});
A.ctAIGo=()=>{const i=$('#ctAI'),t=(i.value||'').trim();if(!t){toast('Type or say who you’re looking for');return}const f=parseNL(t);
  if(!f.length){S.ct.aiMsg='I couldn’t turn that into filters. Try a city, postal code, product, time period or stage — e.g. “women in Mississauga who bought internet in the last 3 months”.';rr();return}
  S.ct.filters=f;const missing=/bought|purchas/.test(t)&&!/last|past/.test(t)?' You didn’t say <b>when</b> they bought — I used “any time”. Want a time period?':'';
  S.ct.aiMsg=`I understood: <b>${f.map(sayF).map(esc).join(' · ')}</b>. ${ctList().length} people match.${missing} <div class="row" style="margin-top:6px">${btn('Save as folder','saveFolder',{k:'xs primary',i:'folderplus'})}${btn('Start a campaign','ctCamp',{k:'xs'})}${btn('Undo','fClear',{k:'xs ghost'})}</div>`;rr()};
