function fEditor(){const m=S.modal,d=FD[m.k],v=m.v;let e='';
 if(d.type==='multi')e=`<div class="choice">${d.opts.map(o=>{const val=Array.isArray(o)?o[0]:o,l=Array.isArray(o)?o[1]:o;return `<button class="${v.includes(val)?'on':''}" data-act="fvT" data-v="${esc(val)}">${esc(l)}</button>`}).join('')}</div><span class="help">Pick as many as you like.</span>`;
 if(d.type==='tags')e=led('fv',v,d.ph,{sample:m.k==='zip'?'L5B':'King St W'});
 if(d.type==='text')e=`<input class="in" value="${esc(v)}" data-inp="fvS" placeholder="Type a value" data-autofocus>${d.demo?'<span class="help">Shown to list every filter — doesn’t change the sample.</span>':''}`;
 if(d.type==='one')e=seg(d.opts.map(o=>[o[0],o[1]]),v,'fvB');
 if(d.type==='yn')e=seg([['yes','Yes'],['no','No']],v,'fvB');
 if(d.type==='range')e=`<div class="row"><input class="in auto num" type="number" style="width:90px" value="${v[0]}" data-chg="fvR" data-i="0" aria-label="From"> to <input class="in auto num" type="number" style="width:90px" value="${v[1]}" data-chg="fvR" data-i="1" aria-label="To"></div>`;
 if(d.type==='bought')e=`<div class="fgrid two">${fld('Product',`<select class="in" data-chg="fvO" data-key="p"><option value="any">Any product</option>${uniq(Object.values(D.products).flatMap(p=>p.cats.flatMap(c=>c.items.map(i=>i[0])))).map(p=>`<option ${v.p===p?'selected':''}>${esc(p)}</option>`).join('')}</select>`)}${fld('When',`<select class="in" data-chg="fvO" data-key="w">${WITHIN.map(w=>`<option value="${w[0]}" ${v.w===w[0]?'selected':''}>In the ${w[1]}</option>`).join('')}</select>`)}</div>`;
 if(d.type==='recency')e=`<div class="row">${seg([['in','Contacted'],['out','Not contacted']],v.m,'fvOB','data-key="m"')} in the last <select class="in sm auto" data-chg="fvO" data-key="d">${['7','14','30','60','90'].map(x=>`<option ${v.d===x?'selected':''}>${x}</option>`).join('')}</select> days</div>`;
 if(d.type==='none')e=`<p class="muted">Nothing else to choose.</p>`;
 return `<div class="lbl">${esc(d.g)} · ${esc(d.l)}</div>${e}<div><div class="lbl" style="margin:8px 0 4px">Reads as</div><div class="banner" style="font-weight:500">${esc(d.say(v))}</div></div>`}
M.filter=m=>{const q=(m.q||'').toLowerCase(),gr=uniq(FIELDS.map(f=>f.g));return MS(m.edit!=null?'Change filter':'Add a filter',`<div class="grid" style="grid-template-columns:230px minmax(0,1fr);gap:0;margin:-20px;min-height:380px"><div style="border-right:1px solid var(--line-2);padding:10px;overflow-y:auto;max-height:60vh"><input class="in sm" placeholder="Search ${FIELDS.length} filters" value="${esc(m.q)}" data-inp="fq" aria-label="Search filters" style="margin-bottom:6px">${gr.map(g=>{const fs=FIELDS.filter(f=>f.g===g&&f.l.toLowerCase().includes(q));return fs.length?`<div class="eyebrow" style="padding:10px 6px 4px">${g}</div>${fs.map(f=>`<button class="lr" style="padding:6px 8px;border:0;border-radius:6px;${m.k===f.k?'background:var(--primary-soft);color:var(--primary-text)':''}" data-act="fPick" data-k="${f.k}">${esc(f.l)}</button>`).join('')}`:''}).join('')}</div><div style="padding:20px" class="stack-s" id="fe">${fEditor()}</div></div>`,`${btn('Cancel','close',{k:'ghost'})}${btn(m.edit!=null?'Update filter':'Add filter','fApply',{k:'primary'})}`,'w')};
