 const tree=(p,dep)=>D.folders.filter(f=>f.parent===p).map(f=>`<button class="${cur===f.id?'on':''}" style="padding-left:${8+dep*16}px" data-act="fGo" data-id="${f.id}" data-ctx="folder" data-fid="${f.id}">${ic('folder',14)}<span class="trunc">${esc(f.name)}</span><span class="c">${nf(fTotal(f.id))}</span></button>${tree(f.id,dep+1)}`).join('');
