/* ---------- Database health (dead numbers, scoring) ---------- */
function vHealth(){const by=s=>D.contacts.filter(c=>scoreOf(c)===s);const dead=by('Dead'),nr=by('Not responding');const L=dead.concat(nr);
 return `<div class="kpis" style="margin-bottom:16px">${['Hot','Warm','Cold','Not responding','Dead'].map(s=>kpi(s,by(s).length,{Hot:'Replied & interested',Warm:'Recent activity',Cold:'Quiet for 2+ weeks','Not responding':'3+ tries, no reply',Dead:'Matches a dead-number rule'}[s],{act:'ctQuick',a:`data-k="score" data-v="${s}"`,dk:s==='Dead'?'neg':'mut'})).join('')}</div>
 <div class="split"><div class="card"><div class="card-h"><h3>Dead & not responding</h3><div class="row">${aiBtn('Find updated info with AI','hFind','data-all="1"','sm')}${btn('Remove selected','hRemove',{k:'sm danger',d:!S.ct.hsel.size})}</div></div><div class="tw"><table class="t compact"><thead><tr><th class="cb"></th><th>Name</th><th>Phone</th><th>Tries</th><th>No reply</th><th>Status</th><th>Rule matched</th><th></th></tr></thead><tbody>
 ${L.map(c=>{const f=S.ct.found[c.id];return `<tr><td class="cb"><input type="checkbox" data-act="hSel" data-id="${c.id}" ${S.ct.hsel.has(c.id)?'checked':''} aria-label="Select"></td><td><button class="lnk" data-act="openContact" data-id="${c.id}">${esc(cname(c))}</button></td><td class="num">${esc(c.phone)}</td><td class="num">${c.attempts}</td><td class="num">${c.noReply}</td><td>${scoreBdg(c)}</td><td class="small muted">${scoreOf(c)==='Dead'?'No reply after 5 texts':'3+ tries, no reply'}</td><td>${f==='busy'?'<span class="spin"></span>':f?`<span class="row nw"><span class="small">New number <b>${f}</b> found</span>${btn('Update','hUpd',{k:'xs primary',a:`data-id="${c.id}"`})}</span>`:`<span class="row nw">${aiBtn('Find new info','hFind',`data-id="${c.id}"`,'xs')}${btn('Keep','hKeep',{k:'xs ghost',a:`data-id="${c.id}"`})}</span>`}</td></tr>`}).join('')}</tbody></table></div></div>
 <div class="stack"><div class="card"><div class="card-h"><h3>Dead-number rules</h3>${btn('Edit','ctSettings',{k:'xs'})}</div><div class="card-b tight">${D.deadRules.map((r,i)=>optRow(esc(r.t),'',sw(r.on,'deadRule',`data-i="${i}"`))).join('')}</div></div>
 <div class="card pad stack-s"><h3>${ic('spark',14)} How scoring works</h3><p class="small muted">Every reply, answered call and opened email raises the score. No replies lower it. Dead numbers are found from failed messages and your rules — so you never pay to message them again.</p></div></div></div>`}
A.hSel=el=>{const s=S.ct.hsel,id=el.dataset.id;s.has(id)?s.delete(id):s.add(id);rr()};
A.hFind=el=>{const ids=el.dataset.all?D.contacts.filter(c=>/Dead|Not responding/.test(scoreOf(c))).map(c=>c.id):[el.dataset.id];ids.forEach(id=>S.ct.found[id]='busy');rr();setTimeout(()=>{ids.forEach((id,i)=>S.ct.found[id]=i%3===2?null:'(905) 555-0'+(160+i));if(S.view==='contacts')rr();toast('AI search finished — new numbers found for '+ids.filter((_,i)=>i%3!==2).length,true)},1400)};
A.hUpd=el=>{const c=byId(el.dataset.id);c.phone=S.ct.found[c.id];c.noReply=0;c.attempts=0;delete S.ct.found[c.id];rr();toast('Number updated — '+cname(c)+' is active again')};
A.hKeep=el=>{toast('Kept — we’ll stop flagging this contact for 90 days')};
A.hRemove=()=>openM('confirm',{title:`Remove ${S.ct.hsel.size} contacts?`,body:'They’ll be deleted from your database and every folder. This keeps your data fresh. You can restore them for 30 days.',act:'hRemoveYes',ok:'Remove',danger:1});
A.hRemoveYes=()=>{D.contacts=D.contacts.filter(c=>!S.ct.hsel.has(c.id));S.ct.hsel.clear();closeM();rr();toast('Removed')};
