/* ---------- tiles: missing details, duplicates ---------- */
A.ctMissing=()=>openM('missing');
M.missing=()=>{const f=[['Name',c=>!c.name],['Email',c=>!c.email],['Address',c=>!c.address],['Postal code',c=>!c.zip],['Language',c=>!c.lang]];return MS('Missing details',`<p class="muted">Breakdown for the sample. The AI searches data providers and the public web, then matches what it finds. If nothing is found, the field stays missing.</p><div class="card tw"><table class="t"><thead><tr><th>Field</th><th class="r">Missing</th><th></th></tr></thead><tbody>${f.map(([n,t])=>{const k=D.contacts.filter(t).length;return `<tr><td>${n}</td><td class="r num"><b>${k}</b></td><td class="r">${k?btn('Show them','missShow',{k:'xs',a:`data-f="${n}"`})+' '+aiBtn('Fill with AI','enrichField',`data-f="${n}"`,'xs'):'<span class="bdg good">Complete</span>'}</td></tr>`}).join('')}</tbody></table></div>`,`${btn('Close','close',{k:'ghost'})}${aiBtn('Fill everything with AI','enrich')}`)};
A.missShow=el=>{closeM();S.ct.tab='all';S.ct.view='rows';S.ct.filters=el.dataset.f==='Name'?[{k:'hasName',v:'no'}]:el.dataset.f==='Email'?[{k:'hasEmail',v:'no'}]:[];if(el.dataset.f==='Address')S.ct.q='';rr()};
A.enrichField=el=>A.enrich(el);
A.enrich=el=>{closeM();const L=S.ct.sel.size?[...S.ct.sel].map(byId):D.contacts;const needE=L.filter(c=>!c.email),needN=L.filter(c=>!c.name),needA=L.filter(c=>!c.address);openM('enrichRun',{rows:[['Data provider A','Email, phone, job'],['Data provider B','Email, address'],['Data provider C','Mobile number, line type'],['AI web search','Names, addresses, public profiles'],['Check','Makes sure each email exists']].map(r=>({n:r[0],d:r[1],st:'wait',f:0})),e:needE.length,n:needN.length,a:needA.length,done:false});
 let i=0;const step=()=>{if(!S.modal||S.modal.t!=='enrichRun')return;const m=S.modal;if(i<5){m.rows[i].st='run';renderModal();setTimeout(()=>{if(!S.modal||S.modal.t!=='enrichRun')return;const take=[.45,.25,.1,.12,0][i];const got=needE.splice(0,Math.ceil(m.e*take));got.forEach(c=>{c.email=`${(c.first||'contact').toLowerCase()}.${(c.last||'x').toLowerCase()}@gmail.com`});if(i===3){needN.forEach(c=>{c.first=pick(FN_F);c.last=pick(LN);c.name=c.first+' '+c.last});needA.slice(0,Math.ceil(needA.length*.7)).forEach(c=>c.address=rint(10,900)+' '+pick(STREETS))}m.rows[i].f=i===4?Math.max(0,m.e-needE.length-1):got.length+(i===3?m.n+Math.ceil(m.a*.7):0);m.rows[i].st='done';i++;renderModal();step()},600)}else{m.done=true;renderModal();if(S.view==='contacts')rr()}};step()};
M.enrichRun=m=>MS(`${ic('spark',16)} Filling missing data`,`<p class="muted">Looking for <b>${m.e} emails</b>, <b>${m.n} names</b> and <b>${m.a} addresses</b>. Each source only gets the people the one before couldn’t find — you only pay when something is found.</p><div class="stack-s">${m.rows.map((r,i)=>`<div class="banner" style="padding:8px 12px;${r.st==='run'?'border-color:var(--ai)':''}"><span class="bdg">${i+1}</span><div class="grow"><b>${r.n}</b><div class="small muted">${r.d}</div></div>${r.st==='run'?'<span class="spin"></span>':r.st==='done'?bdg('found '+r.f,r.f?'good':''):'<span class="small faint">waiting</span>'}</div>`).join('')}</div>${m.done?`<div class="banner ai">${ic('check',15)}Done. New values are tagged with where they came from. Anything not found stays marked “Missing”.</div>`:''}`,m.done?btn('See results','close',{k:'primary'}):btn('Run in background','close'),'');
A.ctDups=()=>openM('dups',{choice:{}});
M.dups=m=>MS('Duplicates · 1,202 detected',`<p class="muted">Nothing is lost: “Smart merge” keeps every field, all history and every conversation on one person.</p><div class="row">${btn('Smart-merge all','dupAll',{k:'sm primary',i:'spark',a:'data-v="Smart merge"'})}${btn('Skip all','dupAll',{k:'sm',a:'data-v="Skip"'})}</div><div class="card tw"><table class="t"><thead><tr><th>Record A</th><th>Record B</th><th>Why</th><th>What to do</th></tr></thead><tbody>${D.dups.map((d,i)=>`<tr><td class="wrap"><b>${esc(d.a.name)}</b><div class="small muted">${esc(d.a.phone)} · ${esc(d.a.email||'no email')}<br>${esc(d.a.src)}</div></td><td class="wrap"><b>${esc(d.b.name)}</b><div class="small muted">${esc(d.b.phone)} · ${esc(d.b.email||'no email')}<br>${esc(d.b.src)}</div></td><td>${bdg(d.why)}</td><td>${sel(['Smart merge','Merge (keep A)','Overwrite A with B','Keep both','Skip'],m.choice[i]||'Smart merge',`data-chg="dupPick" data-i="${i}" aria-label="Choice"`,'sm auto')}</td></tr>`).join('')}</tbody></table></div>`,`${btn('Cancel','close',{k:'ghost'})}${btn('Apply','dupApply',{k:'primary'})}`,'w');
