M.addContact=m=>MS('Add a contact',`<div class="fgrid two">${fld('First name','<input class="in" id="acF" data-autofocus>')}${fld('Last name','<input class="in" id="acL">')}${fld('Mobile','<input class="in" id="acP" placeholder="(905) 555-0100">')}${fld('Email','<input class="in" id="acE">')}${fld('Address','<input class="in" id="acA">')}${fld('City','<input class="in" id="acC" value="Mississauga">')}${fld('Folder',sel(D.folders.filter(f=>!f.grp).map(f=>[f.id,f.name]),'f1','id="acFo"'))}${fld('Lead source',sel(D.sources.map(s=>s.n),'Referral','id="acS"'))}${fld('Stage',sel(['New','Contacted','Interested','Qualified'],'New','id="acSt"'))}${fld('Campaign',sel([['','None']].concat(D.campaigns.map(c=>[c.id,c.name])),'','id="acK"'))}${m.custom.map((f,i)=>fld(esc(f.n)+` <span class="faint small">· custom</span>`,f.t==='Dropdown'?`<select class="in">${f.o.split(',').map(o=>`<option>${esc(o.trim())}</option>`).join('')}</select>`:'<input class="in">')).join('')}</div>
 <div class="banner"><b>${ic('plus',14)} Create a custom field</b><input class="in sm auto" id="cfN" placeholder="Field name, e.g. Current carrier" style="width:220px">${sel(['Text','Dropdown','Number','Date'],'Text','id="cfT"','sm auto')}<input class="in sm auto" id="cfO" placeholder="Options (for dropdown)" style="width:200px">${btn('Add field','cfAdd',{k:'xs'})}</div>
 <div class="row">${sw(true,'noop')}<span class="small">They agreed to texts and calls</span>${sw(true,'noop')}<span class="small">Fill missing details with AI</span></div>`,`${btn('Cancel','close',{k:'ghost'})}${btn('Add contact','acSave',{k:'primary'})}`,'w');
A.cfAdd=()=>{const n=$('#cfN').value.trim();if(!n){toast('Name the field');return}S.modal.custom.push({n,t:$('#cfT').value,o:$('#cfO').value||'Option 1, Option 2'});D.fields.push([n,$('#cfT').value]);renderModal();toast(`“${n}” added — it’s now a filter and a merge field too`)};
A.acSave=()=>{const f=$('#acF').value.trim(),l=$('#acL').value.trim();const k=$('#acK').value||null;const c={id:'c'+(D.contacts.length+200),first:f,last:l,name:(f+' '+l).trim(),gender:'F',age:30,phone:$('#acP').value||'(905) 555-0100',email:$('#acE').value,address:$('#acA').value,city:$('#acC').value,region:'ON',country:'Canada',zip:'L5B',folder:$('#acFo').value,camp:k,stage:$('#acSt').value,dir:(D.sources.find(s=>s.n===$('#acS').value)||{dir:'out'}).dir,source:$('#acS').value,agent:null,purchase:null,last:0,attempts:0,noReply:0,consent:{sms:true,call:true,email:true,wa:true},dnc:false,tags:[],lang:'English',notes:'',custom:{}};D.contacts.unshift(c);closeM();rr();toast((c.name||'Contact')+' added')};
A.import=()=>openM('import',{step:1});
M.import=m=>{const st=m.step;const steps=['Upload','Match columns','Folder & duplicates','Done'];let b='';
 if(st===1)b=`<div class="card pad stack" style="align-items:center;text-align:center;border-style:dashed">${ic('upload',28)}<h3>Drop a file here — any format</h3><p class="muted small">CSV, Excel, Google Sheets export, vCard, PDF lists or even a photo of a list. Any column names work — AI matches them.</p><div class="row" style="justify-content:center"><label class="btn primary">${ic('file',14)}Choose file<input type="file" hidden data-chg="impFile"></label>${btn('Use a sample file','impSample',{k:''})}</div></div>`;
 if(st===2)b=`<div class="banner ai">${ic('spark',15)}<span>AI matched <b>8 of 8</b> columns in <b>${esc(m.file)}</b> (20,000 rows). Check anything marked “check”.</span></div><div class="card tw"><table class="t"><thead><tr><th>Column in your file</th><th>Example</th><th>Goes into</th><th>How sure</th></tr></thead><tbody>${[['Full Name','Maria Rivera','Name',99],['Tel #','905-555-2187','Mobile',97],['E-mail','maria.rivera@gmail.com','Email',99],['Street','214 King St W','Address',95],['Postal','L5B 2C4','Postal code',94],['Last Product','Internet','Last purchase',88],['Purchase Dt','2026-08-13','Date sold',86],['Provider','Bell','Current carrier (custom field)',72]].map(r=>`<tr><td><b>${r[0]}</b></td><td class="muted">${r[1]}</td><td>${sel([r[2],'Don’t import','+ Create a new field…'],r[2],'','sm auto')}</td><td>${r[3]>80?bdg(r[3]+'%','good'):bdg(r[3]+'% · check','warn')}</td></tr>`).join('')}</tbody></table></div>`;
 if(st===3)b=`${m.dnc?'':`<div class="fgrid two">${fld('Save into folder','<input class="in" id="imF" value="Mississauga Leads (Oct)">')}${fld('Inside group',sel([['','Top level']].concat(D.folders.filter(f=>f.grp).map(f=>[f.id,f.name])),'g1','id="imG"'))}</div>`}<div class="card pad stack-s"><b>312 look like people you already have</b><div class="choice">${['Smart merge (recommended)','Overwrite','Merge, keep existing','Keep both','Skip'].map((o,i)=>`<button class="${(m.dup||0)===i?'on':''}" data-act="impDup" data-i="${i}">${o}</button>`).join('')}</div></div><div class="card pad stack-s"><b>How did these people agree to hear from you?</b><div class="choice">${['Signed up on my website / form','Existing customers','Bought or given this list'].map((o,i)=>`<button class="${(m.cons??1)===i?'on':''}" data-act="impCons" data-i="${i}">${o}</button>`).join('')}</div>${(m.cons??1)===2?'<div class="banner bad small">For bought lists, only email is allowed until each person agrees to texts or calls.</div>':''}</div><div class="row">${sw(true,'noop')}<span class="small">Fill missing details with AI after import</span>${sw(true,'noop')}<span class="small">Skip numbers on Do-Not-Contact</span></div>`;
 if(st===4)b=`<div class="stack" style="align-items:flex-start">${bdg(ic('check',11)+'Import finished','good')}<h2>${m.dnc?'148 numbers added to Do-Not-Contact':'20,000 people are in “Mississauga Leads (Oct)”'}</h2>${m.dnc?'':`<div class="kpis" style="width:100%">${kpi('New people','19,688')}${kpi('Merged','312')}${kpi('Missing emails being filled','4,120')}${kpi('On Do-Not-Contact','207')}</div>`}</div>`;
 return MS(m.dnc?'Import a Do-Not-Contact list':'Import contacts',`<div class="row" style="gap:4px">${steps.map((s,i)=>`<span class="bdg ${i+1===st?'blue':i+1<st?'good':''}">${i+1<st?ic('check',11):i+1+'.'} ${s}</span>`).join(ic('right',12))}</div>${b}`,st===1?btn('Cancel','close',{k:'ghost'}):st<4?`${btn('Back','impStep',{k:'ghost',a:'data-d="-1"'})}${btn(st===3?'Import':'Continue','impStep',{k:'primary',a:'data-d="1"'})}`:`${m.dnc?'':btn('Open folder','impOpen',{k:''})}${btn(m.dnc?'Done':'Start a campaign','impCamp',{k:'primary'})}`,'w')};
