/* ---------- contact profile ---------- */
TITLES.contact=()=>{const c=byId(S.p.id);return `Contacts › <b>${esc(cname(c))}</b>`};
S.cp={hist:'all',edit:null};
function histOf(c){const H=[];const conv=D.convos.filter(v=>v.cid===c.id);
 conv.forEach(v=>{let day='Today';v.items.forEach(it=>{if(it.t==='day'){day=it.text;return}const g=day==='Today'?'Today':day==='Yesterday'?'Yesterday':'This week';
  if(it.t==='m')H.push({g,k:'chat',i:PL[v.plat].i,t:`${it.d==='i'?esc(cname(c)):esc(it.who==='you'?'You':agName(it.who))}: “${esc(it.text.slice(0,90))}${it.text.length>90?'…':''}”`,tip:`<b>${PL[v.plat].l} message</b><br>${it.d==='i'?'From the customer':'Sent by '+(it.who==='you'?'you':agName(it.who)+' (AI)')}`,time:it.time,conv:v.id});
  if(it.t==='call')H.push({g,k:'call',i:'phone',t:`Call · ${it.dur} with ${agName(it.who)} — ${esc(it.summary)}`,tip:'<b>Call</b><br>Recording, summary and transcript',time:it.time,rec:1,conv:v.id});
  if(it.t==='ev'&&it.k==='stage')H.push({g,k:'stage',i:'kanban',t:esc(it.text),tip:'<b>Stage change</b>',time:it.time});
  if(it.t==='ev'&&it.k==='book')H.push({g,k:'book',i:'calendar',t:esc(it.text),tip:'<b>Booking</b>',time:it.time});
  if(it.t==='ev'&&it.k==='sys')H.push({g,k:it.query?'query':'sys',i:it.query?'query':'info',t:esc(it.text),tip:it.query?'<b>Query</b><br>Information only — no booking':'<b>System</b>',time:it.time})})});
 D.emails.filter(e=>e.cid===c.id).forEach(e=>H.push({g:e.time.includes(':')&&!/Fri|Wed|Mon/.test(e.time)?'Today':'This week',k:'email',i:'mail',t:`${e.box==='sent'?'Email sent':'Email received'}: “${esc(e.subj)}”`,tip:'<b>Email</b><br>'+esc(e.body.slice(0,120)),time:e.time}));
 if(c.purchase)H.push({g:'Earlier',k:'sale',i:'dollar',t:`Bought <b>${esc(c.purchase.product)}</b> — ${money(c.purchase.amount)}${/Internet|line|TV/.test(c.purchase.product)?'/mo':''}`,tip:`<b>Sale</b><br>${esc(c.purchase.product)} · ${money(c.purchase.amount)} · ${dNice(c.purchase.date)}`,time:dShort(c.purchase.date)});
 if(!conv.length&&c.camp)H.push({g:c.last<1?'Today':c.last<2?'Yesterday':'Earlier',k:'chat',i:'sms',t:`${agName(c.agent||'s1')} sent the first message for <b>${esc(camp(c.camp).name)}</b>`,tip:'<b>Text message</b>',time:agoTxt(c.last)});
 H.push({g:'Earlier',k:'sys',i:'upload',t:`Added to the database — ${esc(c.source)} · folder ${esc(fName(c.folder))}`,tip:'<b>Created</b>',time:'Sep 12'});
 return H}
VIEWS.contact=()=>{const c=byId(S.p.id)||D.contacts[0],cp=camp(c.camp),H=histOf(c).filter(h=>S.cp.hist==='all'||h.k===S.cp.hist);const e=S.cp.edit;
 const F=[['first','First name'],['last','Last name'],['phone','Mobile'],['email','Email'],['address','Address'],['city','City'],['zip','Postal code'],['country','Country'],['lang','Language'],['age','Age']];
 const grp=['Today','Yesterday','This week','Earlier'];
 return `<div class="page wide" style="max-width:1400px"><button class="back" data-act="nav" data-v="contacts">${ic('arrowl',14)}Contacts</button>
 <div class="ph"><div class="row nw" style="gap:14px">${av(c.name||'?','xl')}<div><h1>${c.name?esc(c.name):'<span class="bdg warn">Name missing</span>'}</h1><div class="row small" style="margin-top:4px"><button class="lnk num" data-act="phoneMenu" data-id="${c.id}" data-pop>${esc(c.phone)}</button><span class="faint">·</span>${esc(c.city)}<span class="faint">·</span>${stagePill(c)}${dirTag(c.dir)}${scoreBdg(c)}${c.dnc?bdg('Do-Not-Contact','bad'):''}</div></div></div>
 <div class="row">${btn('Text','newChatTo',{k:'sm',i:'sms',a:`data-cid="${c.id}"`})}${btn('Call','phoneMenu',{k:'sm',i:'phone',a:`data-id="${c.id}" data-pop`})}${btn('Email','composeTo',{k:'sm',i:'mail',a:`data-cid="${c.id}"`})}${btn('Book','bookFor',{k:'sm',i:'calendar',a:`data-cid="${c.id}"`})}${btn('Send quotation','quote',{k:'sm',i:'receipt',a:`data-cid="${c.id}"`})}${btn('Record sale','bulk',{k:'sm',i:'dollar',a:`data-k="sale" data-one="${c.id}"`})}${aiBtn('Analyze with AI','analyzeContact',`data-id="${c.id}"`,'sm')}</div></div>
 <div class="grid" style="grid-template-columns:300px minmax(0,1fr) 300px;align-items:start">
  <div class="card"><div class="card-h"><h3>Details</h3>${aiBtn('Fill missing','enrich','','xs')}</div><div class="card-b tight">${F.map(([k,l])=>`<div class="optrow"><div style="min-width:0;flex:1"><div class="small muted">${l}</div>${e===k?`<input class="in sm" id="cpE" value="${esc(c[k])}" data-enter="cpSave" data-k="${k}" data-autofocus>`:`<div class="trunc">${c[k]?esc(c[k]):'<span class="bdg warn">Missing</span>'}</div>`}</div>${e===k?btn('Save','cpSave',{k:'xs primary',a:`data-k="${k}"`}):iconBtn('edit','cpEdit','Edit',`data-k="${k}"`,'xs')}</div>`).join('')}
   ${D.fields.slice(0,3).map(f=>`<div class="optrow"><div><div class="small muted">${esc(f[0])} <span class="faint">· custom</span></div><div>${esc(c.custom[f[0]]||'—')}</div></div></div>`).join('')}
   <button class="btn link small" style="margin:8px 0" data-act="addContactField">${ic('plus',13)}Add a custom field</button>
   <div class="divider"></div><div class="small muted" style="margin-top:8px">Permission</div>${[['sms','Texts'],['call','Calls'],['email','Emails'],['wa','WhatsApp']].map(([k,l])=>optRow(l,'',sw(c.consent[k],'consent',`data-k="${k}" data-id="${c.id}"`))).join('')}</div></div>
  <div class="card"><div class="card-h"><h3>Journey</h3>${seg([['all','All'],['chat','Chats'],['call','Calls'],['email','Emails'],['sale','Sales'],['stage','Stages'],['book','Bookings']],S.cp.hist,'cpHist')}</div><div class="card-b" style="padding-top:4px">
   ${grp.map(g=>{const it=H.filter(h=>h.g===g);return it.length?`<div class="hist-g">${g}</div>${it.map(h=>`<div class="hi"><span class="hic ${h.k}" data-tip="${h.tip}">${ic(h.i,14)}</span><div class="small">${h.t}${h.rec?`<div class="callc" style="margin-top:6px;width:100%"><div class="wave"><button class="pl" data-act="toast" data-m="Playing recording (prototype)" aria-label="Play">${ic('play',12)}</button>${waveSvg()}</div>${btn('Open transcript','openConvo',{k:'xs',a:`data-id="${h.conv}"`})}</div>`:''}</div><span class="xs faint">${h.time}${h.conv&&!h.rec?` · <button class="btn link xs" data-act="openConvo" data-id="${h.conv}">Open</button>`:''}</span></div>`).join('')}`:''}).join('')||empty('Nothing here yet.')}</div></div>
  <div class="stack"><div class="card"><div class="card-h"><h3>Campaign & stage</h3></div><div class="card-b stack-s">${cp?`<button class="lnk" data-act="nav" data-v="campaign" data-p='{"id":"${cp.id}"}'>${dirIc(cp.dir)} ${esc(cp.name)}</button>${sel(stagesOf(cp).map(s=>s.n),c.stage,`data-chg="cpStage" data-id="${c.id}" aria-label="Stage"`)}<span class="help">Changing it here updates Stages, dashboards and every agent.</span>`:`<span class="muted small">Not in a campaign</span>${btn('Add to campaign','bulk',{k:'sm',a:`data-k="camp" data-one="${c.id}"`})}`}<div class="divider"></div><dl class="kv"><dt>Folder</dt><dd><button class="lnk" data-act="openFolder" data-id="${c.folder}">${esc(fName(c.folder))}</button></dd><dt>Lead source</dt><dd>${dirIc(c.dir)} ${esc(c.source)}</dd><dt>Agent</dt><dd>${c.agent?`<button class="ai-tag" data-act="openAgent" data-id="${c.agent}">${ic('spark',10)}${agName(c.agent)}</button>`:'—'}</dd><dt>Tries</dt><dd>${c.attempts} · ${c.noReply} without reply</dd></dl></div></div>
   <div class="card"><div class="card-h"><h3>Purchases</h3>${btn('Record sale','bulk',{k:'xs',a:`data-k="sale" data-one="${c.id}"`})}</div><div class="card-b tight">${c.purchase?`<div class="hi"><span class="hic sale">${ic('dollar',14)}</span><div class="small"><b>${esc(c.purchase.product)}</b><div class="muted">${money(c.purchase.amount)} · ${dNice(c.purchase.date)}</div></div></div>`:'<p class="small muted" style="padding:8px 0">No purchases yet.</p>'}</div></div>
   <div class="card"><div class="card-h"><h3>Notes</h3></div><div class="card-b"><textarea class="in" placeholder="Notes for your team and agents" data-inp="cpNote" data-id="${c.id}">${esc(c.notes)}</textarea></div></div></div></div></div>`};
A.cpEdit=el=>{S.cp.edit=el.dataset.k;rr()};
A.cpSave=el=>{const c=byId(S.p.id),k=el.dataset.k;c[k]=$('#cpE').value;if(k==='first'||k==='last')c.name=(c.first+' '+c.last).trim();S.cp.edit=null;rr();toast('Saved — updated everywhere')};
A.cpHist=el=>{S.cp.hist=el.dataset.v;rr()};
C.cpStage=el=>{const c=byId(el.dataset.id);c.stage=el.value;rr();toast('Stage set to '+el.value+' — Stages and agents updated')};
I.cpNote=el=>{byId(el.dataset.id).notes=el.value};
A.consent=el=>{const c=byId(el.dataset.id);c.consent[el.dataset.k]=el.checked;toast((el.checked?'Allowed ':'Stopped ')+el.dataset.k+' for '+cname(c))};
A.addContactField=()=>openM('addContact',{custom:[]});
A.analyzeContact=el=>{const c=byId(el.dataset.id);openM('aiNote',{title:'AI summary · '+cname(c),body:`<ul><li>${esc(cname(c))} is <b>${scoreOf(c).toLowerCase()}</b> — ${c.attempts} tries, last contact ${agoTxt(c.last)}.</li><li>Current stage: <b>${esc(c.stage)}</b>${c.camp?' in '+esc(camp(c.camp).name):''}.</li><li>Best channel: ${c.consent.wa?'WhatsApp':'SMS'} in the evening (6–8 PM).</li><li>Suggested next step: ${/Pending/.test(c.stage)?'check in on Thursday with the Oct 31 deadline.':'offer a quick call to confirm details.'}</li></ul>`})};
M.aiNote=m=>MS(`${ic('spark',16)} ${esc(m.title)}`,m.body,btn('Close','close',{k:'primary'}),'n');
